                pos, delta = best_insertion_position(routes[rid], v)
                if delta < best_delta:
                    best_delta = delta
                    best_rid = rid
                    best_pos = pos
        if best_rid == -1:
            routes.append([v])
            r_demand.append(d)
        else:
            routes[best_rid].insert(best_pos, v)
            r_demand[best_rid] += d

    # ---- Feasibility repair for any unexpected capacity violations ----
    # Move customers out of infeasible routes to best feasible targets.
    # (If none feasible, keep as singleton; feasibility constraints may be impossible.)
    if len(routes) > 0:
        for rid in range(len(routes)):
            while r_demand[rid] > cap and len(routes[rid]) > 1:
                # remove one customer with largest "loss" if moved
                route = routes[rid]
                remove_idx = -1
                best_loss = -1
                # compute cost impact removing each node
                for k in range(len(route)):
                    node = route[k]
                    before = route_cost(route)
                    tmp = route[:k] + route[k+1:]
                    after = route_cost(tmp)
                    loss = before - after
                    if loss > best_loss:
                        best_loss = loss
                        remove_idx = k
                node = route[remove_idx]
                routes[rid].pop(remove_idx)
                r_demand[rid] -= demands[node]

                # insert node into best feasible route (or new)
                d = demands[node]
                best_rid2 = -1
                best_delta2 = 10**30
                best_pos2 = 0
                for rr in range(len(routes)):
                    if r_demand[rr] + d <= cap:
                        pos, delta = best_insertion_position(routes[rr], node)
                        if delta < best_delta2:
                            best_delta2 = delta
                            best_rid2 = rr
                            best_pos2 = pos
                if best_rid2 == -1:
                    routes.append([node])
                    r_demand.append(d)
                else:
                    routes[best_rid2].insert(best_pos2, node)
                    r_demand[best_rid2] += d

        # Final compaction: remove empty routes
        routes = [r for r in routes if len(r) > 0]

    # ---- Small intra-route local search (deterministic 2-opt style within capacity) ----
    # Only if capacity allows (always) and improve route cost.
    def two_opt_improve(route):
        L = len(route)
        if L < 4:
            return route
        improved = True
        # deterministic single pass with first-improvement
        while improved:
            improved = False
            base_cost = route_cost(route)
            for i in range(0, L - 2):
                for j in range(i + 2, L):
                    if j - i == 1:
                        continue
                    new_route = route[:i + 1] + route[i + 1:j + 1][::-1] + route[j + 1:]
                    new_cost = route_cost(new_route)
                    if new_cost < base_cost:
                        return new_route
        return route

    for rid in range(len(routes)):
        routes[rid] = two_opt_improve(routes[rid])

    return routes
